<template>
  <div class="proposal-plan-details">
    <template v-if="kind==='targets'"><div class="plan-section form-section"><div class="plan-section-head"><div><h3 :class="{'required-section':requiredPlanSections.targets}"><span class="section-index">{{ sectionNumber }}</span>{{ $tr("项目验收目标") }}<span v-if="!requiredPlanSections.targets" class="optional-label">{{ $tr("（选填）") }}</span></h3><p>{{ $tr("{0}。目标值按所选单位保存；人民币项目中，10 万元表示 100000 元。收入和预算按项目币种基本单位填写。", [requiredPlanSections.targets ? $tr("至少填写一项验收目标") : $tr("可由主负责人预填，也可由子负责人补充")]) }}</p></div><el-button size="small" type="primary" plain @click="addTarget">{{ $tr("增加目标") }}</el-button></div><el-table :data="form.targetLines" size="small"><el-table-column :label="$tr(&quot;类型&quot;)" :label-class-name="form.targetLines?.length ? 'required-column' : ''" width="125"><template #default="{row}"><el-select v-model="row.targetType" @change="changeTargetType(row)"><el-option v-for="(label,value) in targetTypeLabel" :key="value" :label="label" :value="value"/></el-select></template></el-table-column><el-table-column :label="$tr(&quot;目标名称&quot;)" :label-class-name="form.targetLines?.length ? 'required-column' : ''" min-width="180"><template #default="{row}"><el-input v-model="row.targetName" maxlength="160"/></template></el-table-column><el-table-column :label="$tr(&quot;目标值&quot;)" :label-class-name="form.targetLines?.some(row=>row.targetType!=='DELIVERY') ? 'required-column' : ''" width="145"><template #default="{row}"><span v-if="row.targetType==='DELIVERY'">{{ $tr("通过验收") }}</span><el-input-number v-else v-model="row.targetValue" :min="0" :max="99999999999999.99" :precision="4"/></template></el-table-column><el-table-column :label="$tr(&quot;单位&quot;)" :label-class-name="form.targetLines?.some(row=>row.targetType!=='DELIVERY') ? 'required-column' : ''" width="140"><template #default="{row}"><span v-if="row.targetType==='DELIVERY'">—</span><el-select v-else :model-value="row.unit" @update:model-value="changeTargetUnit(row,$event)" filterable :placeholder="$tr(&quot;选择单位&quot;)" :aria-label="$tr(&quot;目标单位&quot;)" style="width:100%"><el-option v-if="row.unit && !targetUnitOptions.includes(row.unit)" :label="$tr(row.unit)" :value="row.unit"/><el-option v-for="unit in targetUnitOptions" :key="unit" :label="$tr(unit)" :value="unit"/></el-select></template></el-table-column><el-table-column :label="dateType==='date' ? $tr(&quot;完成日期&quot;) : $tr(&quot;完成月份&quot;)" width="145"><template #default="{row}"><ProposalMonthPicker :date-type="dateType" v-model="row.dueDate" :start-date="form.planStartDate" :end-date="planEndDate" deadline /><small v-if="lineDateIssue(row.dueDate)" class="danger-text">{{ lineDateIssue(row.dueDate) }}</small></template></el-table-column><el-table-column :label="$tr(&quot;验收依据&quot;)" :label-class-name="form.targetLines?.length ? 'required-column' : ''" min-width="210"><template #default="{row}"><el-input v-model="row.acceptanceEvidence" maxlength="500" :placeholder="$tr(&quot;报表、合同、交付文件等&quot;)"/></template></el-table-column><el-table-column width="55"><template #default="{$index}"><el-button link type="danger" @click="form.targetLines.splice($index,1)">{{ $tr("删") }}</el-button></template></el-table-column></el-table></div></template>
    <template v-else><div class="plan-section form-section"><div class="plan-section-head"><div><h3 :class="{'required-section':requiredPlanSections.revenue}"><span class="section-index">{{ sectionNumber }}</span>{{ $tr("收入测算") }}<span v-if="!requiredPlanSections.revenue" class="optional-label">{{ $tr("（选填）") }}</span></h3><p>{{ $tr("可选择项目开始月前 6 个月；有限期项目最晚可选结束月后 6 个月，不限期项目不限制结束月份；金额按项目币种基本单位填写；切换单位会同步整个项目的预算币种。") }}</p></div><el-button size="small" type="primary" plain @click="addRevenue">{{ $tr("增加收入") }}</el-button></div><el-table :data="form.revenueLines" size="small" :empty-text="requiredPlanSections.revenue ? $tr(&quot;请添加收入预测&quot;) : $tr(&quot;暂无收入测算&quot;)"><el-table-column :label="$tr(&quot;收入方式&quot;)" :label-class-name="form.revenueLines?.length ? 'required-column' : ''" width="145"><template #default="{row}"><el-select v-model="row.revenueType"><template #label="{ label }">{{ legacyRevenueTypeLabels[row.revenueType] || label }}</template><el-option v-for="(label,value) in revenueTypeLabel" :key="value" :label="label" :value="value"/></el-select></template></el-table-column><el-table-column :label="$tr(&quot;收入项目&quot;)" :label-class-name="form.revenueLines?.length ? 'required-column' : ''" min-width="150"><template #default="{row}"><el-input v-model="row.itemName" maxlength="160" :placeholder="$tr(&quot;商品或服务&quot;)"/><small v-if="row.scenario && row.scenario!=='BASE'" class="legacy-revenue-note">{{ $tr("历史备选收入，未计入当前测算") }}</small></template></el-table-column><el-table-column :label="$tr(&quot;预计金额&quot;)" :label-class-name="form.revenueLines?.length ? 'required-column' : ''" width="165"><template #default="{row}"><el-input-number v-model="row.expectedAmount" :min="0" :max="99999999999.99" :precision="2" controls-position="right"/></template></el-table-column><el-table-column :label="$tr(&quot;金额单位&quot;)" width="115"><template #default><el-select :model-value="form.baseCurrency" @update:model-value="emit('change-currency',$event)" :disabled="!!form.parentProjectId" :aria-label="$tr(&quot;收入金额单位&quot;)"><el-option v-if="form.baseCurrency==='USD'" label="USD" value="USD" disabled/><el-option label="CNY" value="CNY"/><el-option label="VND" value="VND"/></el-select></template></el-table-column><el-table-column :label="$tr(&quot;发生方式&quot;)" :label-class-name="form.revenueLines?.length ? 'required-column' : ''" width="125"><template #default="{row}"><el-select v-model="row.occurrenceType" :placeholder="$tr(&quot;一次性&quot;)"><el-option :label="$tr(&quot;一次性&quot;)" value="ONE_TIME"/><el-option :label="$tr(&quot;每日&quot;)" value="DAILY"/><el-option :label="$tr(&quot;每周&quot;)" value="WEEKLY"/><el-option :label="$tr(&quot;每月&quot;)" value="MONTHLY"/></el-select></template></el-table-column><el-table-column :label="dateType==='date' ? $tr(&quot;收入日期 / 开始&quot;) : $tr(&quot;收入月份 / 开始&quot;)" width="145"><template #default="{row}"><ProposalMonthPicker :date-type="dateType" v-model="row.expectedDate" :start-date="form.planStartDate" :end-date="planEndDate" :before-start-months="6" :after-end-months="6" /><small v-if="lineDateIssue(row.expectedDate,'revenue')" class="danger-text">{{ lineDateIssue(row.expectedDate,'revenue') }}</small></template></el-table-column><el-table-column :label="$tr(&quot;依据&quot;)" min-width="170"><template #default="{row}"><el-input v-model="row.assumptionText" maxlength="1000" :placeholder="$tr(&quot;单价、数量、转化率等&quot;)"/></template></el-table-column><el-table-column width="55"><template #default="{$index}"><el-button link type="danger" @click="form.revenueLines.splice($index,1)">{{ $tr("删") }}</el-button></template></el-table-column></el-table></div></template>
  </div>
</template>
<script setup>
import { translateText } from '@/locales/translate'

import { ElMessage } from 'element-plus'
import ProposalMonthPicker from './ProposalMonthPicker.vue'
const legacyRevenueTypeLabels={ADVERTISING:translateText("广告"),SUBSCRIPTION:translateText("订阅"),SAVING:translateText("成本节约")}
defineProps({kind:String,sectionNumber:String,form:Object,requiredPlanSections:Object,targetTypeLabel:Object,targetUnitOptions:Array,revenueTypeLabel:Object,planEndDate:String,lineDateIssue:Function,dateType:String})
const emit=defineEmits(['add-target','add-revenue','change-target-type','change-currency'])
const addTarget=()=>emit('add-target')
const addRevenue=()=>emit('add-revenue')
const changeTargetType=row=>emit('change-target-type',row)
function changeTargetUnit(row,unit){if(row.unit===unit)return;row.unit=unit;if(row.targetValue!=null&&Number(row.targetValue)!==0){row.targetValue=null;ElMessage.info(translateText("单位已切换，请按新单位重新填写目标值"))}if(['元','万元','CNY','USD','VND'].includes(unit))row.targetType='FINANCIAL'}
</script>
<style scoped>
.optional-label{font-size:13px;font-weight:500;color:#657587}.plan-section{margin:12px 0 22px;padding:22px;border:1px solid #d5e0ec;border-radius:12px;background:#fff;box-shadow:0 5px 16px rgba(36,74,119,.06)}.plan-section-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid #e3eaf2}.plan-section-head h3{display:flex;align-items:center;gap:10px;margin:0;color:#1f3048;font-size:20px;line-height:32px}.plan-section-head p{margin:6px 0 0;color:#718096;font-size:13px}.section-index{display:inline-flex;align-items:center;justify-content:center;min-width:38px;height:28px;padding:0 7px;border-radius:7px;background:#e9f3ff;color:#2874c6;font-size:14px;font-weight:700;letter-spacing:.04em}.plan-section :deep(.el-input-number){width:100%}.required-section::before{content:'*';color:var(--el-color-danger);margin-right:-6px}.danger-text{color:#d7474f}.legacy-revenue-note{display:block;margin-top:4px;color:#7d8998;line-height:1.5}
</style>
